INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is the purpose of installing ''flow meters'' and monitoring water/chemical consumption at each wet-processing stage in a modern textile mill?', '["To track resource usage precisely, supporting cost control, process consistency, and sustainability/compliance reporting","Flow meters exist purely for decorative purposes with no operational use","To measure the exact final color shade of dyed fabric","To replace the need for any dye chemical entirely"]'::jsonb, 'To track resource usage precisely, supporting cost control, process consistency, and sustainability/compliance reporting', 'Monitoring water and chemical consumption via flow meters supports accurate costing, helps maintain consistent process recipes (avoiding unintentional over/under-dosing), and provides the data needed for sustainability reporting and regulatory compliance increasingly required in the textile industry.', 1, '{"resource-monitoring"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'Why might a textile mill invest in ''water recycling/reuse'' systems for its wet-processing operations?', '["To reduce fresh water consumption and wastewater discharge volume, lowering both costs and environmental impact","Recycled water always produces better dyeing results than fresh water with no exceptions","Water recycling is required only for garment dyeing, never for any other wet process","Recycling water has no effect on either cost or environmental impact"]'::jsonb, 'To reduce fresh water consumption and wastewater discharge volume, lowering both costs and environmental impact', 'Textile wet processing is highly water-intensive; recycling/reusing treated water (e.g., from rinse baths) for less-sensitive process steps reduces total fresh water intake and the volume of wastewater needing treatment/discharge — both a cost saving and an environmental/sustainability benefit.', 1, '{"water-recycling"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'What is a general reason ''low liquor ratio'' dyeing machines (using less water per kg of fabric than older designs) have become increasingly favored?', '["They reduce water, energy (for heating), and chemical consumption per kg of fabric dyed, lowering costs and environmental impact","Lower liquor ratio always makes dyeing slower with no other benefit","Liquor ratio has no relationship to water, energy, or chemical consumption","Low liquor ratio machines cannot achieve any acceptable dyeing quality"]'::jsonb, 'They reduce water, energy (for heating), and chemical consumption per kg of fabric dyed, lowering costs and environmental impact', 'A lower liquor ratio means less total water volume needs to be heated and dosed with chemicals for the same fabric weight, directly reducing water use, energy consumption (less water to heat), and often total chemical consumption — a significant driver behind modern low-liquor-ratio dyeing machine designs.', 2, '{"low-liquor-ratio"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is ''Oeko-Tex Standard 100'' certification generally concerned with, in the context of finished textile products?', '["Testing finished textile products for the presence of harmful substances (like restricted chemicals, heavy metals, formaldehyde) at levels considered safe for consumer/skin contact","Certifying the exact fiber content percentage of a fabric blend","Certifying only the fabric''s color-fastness properties, with no chemical safety component","A certification that applies only to raw fiber, never to finished dyed/finished textile products"]'::jsonb, 'Testing finished textile products for the presence of harmful substances (like restricted chemicals, heavy metals, formaldehyde) at levels considered safe for consumer/skin contact', 'Oeko-Tex Standard 100 is a widely recognized certification testing finished textile products against limits for numerous potentially harmful substances (certain dyes/chemicals, heavy metals, formaldehyde, pesticide residues, etc.), aiming to assure consumer safety for skin contact.', 1, '{"oeko-tex-certification"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'Why do brands/buyers increasingly require textile mills to hold sustainability/chemical-safety certifications (like Oeko-Tex or bluesign) as part of their sourcing requirements?', '["These certifications provide independent verification that products/processes meet defined safety and environmental standards, helping brands manage compliance and consumer-safety risk across their supply chain","Certifications have no practical value and are purely symbolic with zero supply-chain benefit","Certifications guarantee a specific fabric color, unrelated to safety or environmental standards","Only fully synthetic fiber products can ever qualify for such certifications"]'::jsonb, 'These certifications provide independent verification that products/processes meet defined safety and environmental standards, helping brands manage compliance and consumer-safety risk across their supply chain', 'Third-party certifications give brands independent assurance (beyond just trusting a supplier''s claims) that products/processes meet specific safety and environmental criteria, helping manage regulatory compliance, consumer safety risk, and increasingly important sustainability commitments across complex global supply chains.', 2, '{"sustainability-certification"}'::text[]);
